mapper.select:
SELECT COUNT(*) FROM oss_project p
WHERE p.publish_status = 'published'

AND p.featured = #{featured}

SELECT FROM oss_project_article pa JOIN blog b ON b.id = pa.blog_id AND b.is_published = b'1' JOIN oss_project p ON p.id = pa.project_id AND p.publish_status = 'published'
AND p.category = #{category}
AND EXISTS (SELECT 1 FROM oss_project_tag pt JOIN tag t ON t.id = pt.tag_id WHERE pt.project_id = p.id AND t.tag_name = #{tag})
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY b.create_time DESC, b.id DESC LIMIT #{offset}, #{size}
